\begin{remark}
\label{topping-ch9-roundness-reduction}
\source{topping:page-0121}
\dcref{ch9:7.9}
\group{curvature-pinching}
It is enough to control the nonnegative quantity \(\lambda_3-\lambda_1\),
because
\[
\left|\Ric-\frac13Rg\right|^2\le(\lambda_3-\lambda_1)^2.
\]
\end{remark}

